import{_ as p,a0 as o,w as r,s as t,I as e,x as n,a1 as i,A as l,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"在 Linux 上使用 lspci 命令查看硬件情况 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 lspci 命令查看硬件情况 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 lspci 命令查看硬件情况 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 lspci 命令查看硬件情况 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210907 Use lspci on Linux to see your hardware","title":"在 Linux 上使用 lspci 命令查看硬件情况","tag":"202109","desc":""},"relativePath":"202109/20210907 Use lspci on Linux to see your hardware.md","filePath":"[post].md"}'),c={name:"202109/20210907 Use lspci on Linux to see your hardware.md"};function u(g,s,h,b,I,v){const a=o("Link");return r(),t("div",null,[s[25]||(s[25]=e("h1",{id:"在-linux-上使用-lspci-命令查看硬件情况",tabindex:"-1"},[n("在 Linux 上使用 lspci 命令查看硬件情况 "),e("a",{class:"header-anchor",href:"#在-linux-上使用-lspci-命令查看硬件情况","aria-label":"Permalink to “在 Linux 上使用 lspci 命令查看硬件情况”"},"​")],-1)),s[26]||(s[26]=e("blockquote",null,[e("p",null,"lspci 命令用于显示 Linux 系统上的设备和驱动程序。")],-1)),s[27]||(s[27]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/17/091425l7c8au5c865x7q68.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=n("当你在个人电脑或服务器上运行 Linux 时，有时需要识别该系统中的硬件。",-1)),s[2]||(s[2]=e("code",null,"lspci",-1)),s[3]||(s[3]=n(" 命令用于显示连接到 PCI 总线的所有设备，从而满足上述需求。该命令由 ",-1)),i(a,{href:"https://mj.ucw.cz/sw/pciutils/"},{default:l(()=>[...s[0]||(s[0]=[n("pciutils",-1)])]),_:1}),s[4]||(s[4]=n(" 包提供，可用于各种基于 Linux 和 BSD 的操作系统。",-1))]),s[28]||(s[28]=d(`<h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to “基础用法”">​</a></h3><p>由于访问权限，普通用户运行 <code>lspci</code> 时显示的信息可能会受限，因此可以使用 <code>sudo</code> 运行命令，系统会给出完整的信息图。</p><p>直接运行 <code>lspci</code> 命令会列出 PCI 总线及其连接的设备，下图是在我的媒体中心 PC 上的演示样例。图中是一个基于 AMD Phenom CPU 的系统，所以它有一个 AMD 芯片组，以及 Atheros 无线适配器和 Nvidia 显卡。所有硬件设备都列出了详细信息，例如供应商、名称和型号等：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci</span></span>
<span class="line"><span>00:00.0 Host bridge: Advanced Micro Devices, Inc. [AMD] RS880 Host Bridge</span></span>
<span class="line"><span>00:02.0 PCI bridge: Advanced Micro Devices, Inc. [AMD] RS780 PCI to PCI bridge (ext gfx port 0)</span></span>
<span class="line"><span>00:04.0 PCI bridge: Advanced Micro Devices, Inc. [AMD] RS780/RS880 PCI to PCI bridge (PCIE port 0)</span></span>
<span class="line"><span>00:05.0 PCI bridge: Advanced Micro Devices, Inc. [AMD] RS780/RS880 PCI to PCI bridge (PCIE port 1)</span></span>
<span class="line"><span>00:11.0 SATA controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 SATA Controller [AHCI mode]</span></span>
<span class="line"><span>00:12.0 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB OHCI0 Controller</span></span>
<span class="line"><span>00:12.1 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0 USB OHCI1 Controller</span></span>
<span class="line"><span>00:12.2 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB EHCI Controller</span></span>
<span class="line"><span>00:13.0 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB OHCI0 Controller</span></span>
<span class="line"><span>00:13.1 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0 USB OHCI1 Controller</span></span>
<span class="line"><span>00:13.2 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB EHCI Controller</span></span>
<span class="line"><span>00:14.0 SMBus: Advanced Micro Devices, Inc. [AMD/ATI] SBx00 SMBus Controller (rev 3c)</span></span>
<span class="line"><span>00:14.1 IDE interface: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 IDE Controller</span></span>
<span class="line"><span>00:14.3 ISA bridge: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 LPC host controller</span></span>
<span class="line"><span>00:14.4 PCI bridge: Advanced Micro Devices, Inc. [AMD/ATI] SBx00 PCI to PCI Bridge</span></span>
<span class="line"><span>00:14.5 USB controller: Advanced Micro Devices, Inc. [AMD/ATI] SB7x0/SB8x0/SB9x0 USB OHCI2 Controller</span></span>
<span class="line"><span>00:18.0 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor HyperTransport Configuration</span></span>
<span class="line"><span>00:18.1 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor Address Map</span></span>
<span class="line"><span>00:18.2 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor DRAM Controller</span></span>
<span class="line"><span>00:18.3 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor Miscellaneous Control</span></span>
<span class="line"><span>00:18.4 Host bridge: Advanced Micro Devices, Inc. [AMD] Family 10h Processor Link Control</span></span>
<span class="line"><span>01:00.0 VGA compatible controller: NVIDIA Corporation GK107 [GeForce GTX 650] (rev a1)</span></span>
<span class="line"><span>01:00.1 Audio device: NVIDIA Corporation GK107 HDMI Audio Controller (rev a1)</span></span>
<span class="line"><span>02:00.0 Network controller: Qualcomm Atheros AR9287 Wireless Network Adapter (PCI-Express) (rev 01)</span></span></code></pre></div><h3 id="详细输出" tabindex="-1">详细输出 <a class="header-anchor" href="#详细输出" aria-label="Permalink to “详细输出”">​</a></h3><p>添加 <code>-v</code> 选项会显示每个设备的详细信息，你可以使用 <code>-vv</code> 或 <code>-vvv</code> 来获取更多的设备细节。在 <code>-v</code> 级别，<code>lspci</code> 会显示所有设备的各种子系统和内存地址、中断请求（IRQ）编号和一些其他功能信息。输出信息会非常长。在你的系统上试一试吧。</p><h3 id="使用-grep-过滤搜索" tabindex="-1">使用 grep 过滤搜索 <a class="header-anchor" href="#使用-grep-过滤搜索" aria-label="Permalink to “使用 grep 过滤搜索”">​</a></h3><p>你可能会需要缩小搜索范围。例如，RPM Fusion 网站有安装 Nvidia 图形驱动程序的说明，里面就首先使用了 <code>grep</code> 命令来定位显卡信息。下面是我在笔记本电脑上得到的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci | grep -e VGA</span></span>
<span class="line"><span>00:02.0 VGA compatible controller: Intel Corporation UHD Graphics 620 (rev 07)</span></span>
<span class="line"><span>$ sudo lspci | grep -e 3D</span></span>
<span class="line"><span>01:00.0 3D controller: NVIDIA Corporation GM108M [GeForce MX130] (rev a2)</span></span></code></pre></div><p>下面（LCTT 译注：原文为 “above”，应为作者笔误）的 <code>grep</code> 命令在我的媒体中心 PC 上定位了一个 VGA 设备，但没有显示 3D 设备。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci | grep -e VGA</span></span>
<span class="line"><span>01:00.0 VGA compatible controller: NVIDIA Corporation GK107 [GeForce GTX 650] (rev a1)</span></span>
<span class="line"><span>$ sudo lspci | grep -e 3D</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="按供应商-id-搜索" tabindex="-1">按供应商 ID 搜索 <a class="header-anchor" href="#按供应商-id-搜索" aria-label="Permalink to “按供应商 ID 搜索”">​</a></h3><p>还有另一种无需 <code>grep</code> 的方法可以使用。假设我想确认一下此计算机是否有其他的 Nvidia 设备，在此之前我们还需要一些额外信息，使用 <code>-nn</code> 选项显示的供应商和设备 ID 号。在我的媒体中心 PC 上，此选项会给出我的 VGA 卡、供应商 ID 和设备 ID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci -nn | grep -e VGA</span></span>
<span class="line"><span>01:00.0 VGA compatible controller [0300]: NVIDIA Corporation GK107 [GeForce GTX 650] [10de:0fc6] (rev a1)</span></span></code></pre></div><p>设备名称后的方括号内有用冒号分隔的数字，即供应商和设备 ID。输出表明 Nvidia Corporation 制造的设备的供应商 ID 为 <code>10de</code>。</p><p><code>-d</code> 选项用于指定供应商、设备或类 ID 的所有设备。以下是我系统中的所有 Nvidia 设备（保留 <code>-nn</code> 以解析供应商 ID）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci -nn -d 10de:</span></span>
<span class="line"><span>01:00.0 VGA compatible controller [0300]: NVIDIA Corporation GK107 [GeForce GTX 650] [10de:0fc6] (rev a1)</span></span>
<span class="line"><span>01:00.1 Audio device [0403]: NVIDIA Corporation GK107 HDMI Audio Controller [10de:0e1b] (rev a1)</span></span></code></pre></div><p>从输出中可以看到，除了显卡之外，我还有一个 Nvidia 音频设备。实际上它们都属于同一张 <strong>Nvidia GeForce GTX 650</strong> 卡，但这仍然是一个很好的示例。</p><h3 id="内核模块" tabindex="-1">内核模块 <a class="header-anchor" href="#内核模块" aria-label="Permalink to “内核模块”">​</a></h3><p>结合 PCI 硬件设备，<code>lspci</code> 可以使用 <code>-k</code> 选项显示内核加载了哪些驱动程序模块。我将此选项添加到我的 <code>lspci</code> 命令来查看有关我的 Nvidia 设备的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci -nn -k -d 10de:</span></span>
<span class="line"><span>01:00.0 VGA compatible controller [0300]: NVIDIA Corporation GK107 [GeForce GTX 650] [10de:0fc6] (rev a1)</span></span>
<span class="line"><span> Subsystem: eVga.com. Corp. GK107 [GeForce GTX 650] [3842:2650]</span></span>
<span class="line"><span> Kernel driver in use: nvidia</span></span>
<span class="line"><span> Kernel modules: nvidiafb, nouveau, nvidia_drm, nvidia</span></span>
<span class="line"><span>01:00.1 Audio device [0403]: NVIDIA Corporation GK107 HDMI Audio Controller [10de:0e1b] (rev a1)</span></span>
<span class="line"><span> Subsystem: eVga.com. Corp. GK107 HDMI Audio Controller [3842:2650]</span></span>
<span class="line"><span> Kernel driver in use: snd_hda_intel</span></span>
<span class="line"><span> Kernel modules: snd_hda_intel</span></span></code></pre></div><p>可以看到额外显示了两行：<ruby>正在使用的内核驱动程序<rt>Kernel driver in use</rt></ruby> 和 <ruby>内核模块<rt>Kernel modules</rt></ruby>，其中后者列出了可用于支持该设备的模块。</p><h3 id="同步最新状态" tabindex="-1">同步最新状态 <a class="header-anchor" href="#同步最新状态" aria-label="Permalink to “同步最新状态”">​</a></h3><p>新设备和供应商总是在不断迭代。如果看到显示为 <code>unknown</code> 的设备，说明你的 PCI 设备 ID 数据库可能已过时。有两种方法可以检查更新。<code>-Q</code> 选项会使用 DNS 查询中央数据库，当然，这需要联网。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lspci -Q</span></span></code></pre></div><p>你还可以通过运行命令 <code>update-pciids</code> 来更新本地 PCI ID 数据库。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo update-pciids</span></span>
<span class="line"><span>Downloaded daily snapshot dated 2021-08-22 03:15:01</span></span></code></pre></div><h3 id="了解有关你的硬件的更多信息" tabindex="-1">了解有关你的硬件的更多信息 <a class="header-anchor" href="#了解有关你的硬件的更多信息" aria-label="Permalink to “了解有关你的硬件的更多信息”">​</a></h3>`,28)),e("p",null,[s[6]||(s[6]=n("当然，",-1)),s[7]||(s[7]=e("code",null,"lspci",-1)),s[8]||(s[8]=n(" 只是 Linux 中用于查询系统硬件和软件的诸多命令之一。读者可以在阅读关于 USB 设备的文章，了解有关 Linux 硬件的更多信息：",-1)),i(a,{href:"https://opensource.com/article/20/8/usb-id-repository"},{default:l(()=>[...s[5]||(s[5]=[n("使用此 USB ID 存储库识别 Linux 上的更多设备",-1)])]),_:1}),s[9]||(s[9]=n("。",-1))]),s[29]||(s[29]=e("hr",null,null,-1)),e("p",null,[s[11]||(s[11]=n("via: ",-1)),i(a,{href:"https://opensource.com/article/21/9/lspci-linux-hardware"},{default:l(()=>[...s[10]||(s[10]=[n("https://opensource.com/article/21/9/lspci-linux-hardware",-1)])]),_:1})]),e("p",null,[s[16]||(s[16]=n("作者：",-1)),i(a,{href:"https://opensource.com/users/alanfdoss"},{default:l(()=>[...s[12]||(s[12]=[n("Alan Formy-Duval",-1)])]),_:1}),s[17]||(s[17]=n(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[13]||(s[13]=[n("lujun9972",-1)])]),_:1}),s[18]||(s[18]=n(" 译者：",-1)),i(a,{href:"https://github.com/unigeorge"},{default:l(()=>[...s[14]||(s[14]=[n("unigeorge",-1)])]),_:1}),s[19]||(s[19]=n(" 校对：",-1)),i(a,{href:"https://github.com/turbokernel"},{default:l(()=>[...s[15]||(s[15]=[n("turbokernel",-1)])]),_:1})]),e("p",null,[s[22]||(s[22]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[n("Linux中国",-1)])]),_:1}),s[24]||(s[24]=n(" 荣誉推出",-1))])])}const D=p(c,[["render",u]]);export{k as __pageData,D as default};
